// Classify error and calculate retry backoff
const input = $json;
const execution = input.execution || {};
const error = input.error || {};

const msg = String(error.message || input.error_message || 'Unknown technical failure');
const nodeName = error.node?.name || input.node || 'Unknown Node';
const wfName = input.workflow?.name || input.workflow || 'Unknown Workflow';
const jobId = input.internal_job_id || execution.customData?.internal_job_id || 'N/A';
const business = input.business || execution.customData?.business || 'N/A';
const currentRetries = Number(input.retry_count || 0);

// Determine classification:
// TRANSIENT: Rate limits (429), timeouts, 502/503/504 gateway issues, network socket resets
// BUSINESS_RULE: Validation errors, missing assets, duplicate state, unauthorized token
let errorType = 'SYSTEM';
let isTransient = false;

if (/429|rate limit|timeout|ETIMEDOUT|ECONNRESET|502|503|504/i.test(msg)) {
  errorType = 'TRANSIENT';
  isTransient = true;
} else if (/validation|insufficient|missing|duplicate|unauthorized|stale/i.test(msg)) {
  errorType = 'BUSINESS_RULE';
  isTransient = false;
}

const canRetry = isTransient && currentRetries < 2;
const nextRetry = currentRetries + 1;
const backoffMs = Math.pow(2, nextRetry) * 2500; // 5s, 10s backoff

const errId = `ERR_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`;

return [{
  json: {
    error_id: errId,
    timestamp: new Date().toISOString(),
    workflow: wfName,
    internal_job_id: jobId,
    business: business,
    node: nodeName,
    error_type: errorType,
    error_message: msg,
    retry_count: currentRetries,
    can_retry: canRetry,
    next_retry_count: nextRetry,
    backoff_ms: backoffMs,
    resolved: false,
    resolution: canRetry ? `SCHEDULED_RETRY_${nextRetry}` : 'LOGGED_REQUIRING_ATTENTION'
  }
}];

// Trigger retry event or update retry counter
return [{
  json: {
    status: 'RETRY_INITIATED',
    retry_count: $json.next_retry_count,
    workflow: $json.workflow,
    internal_job_id: $json.internal_job_id
  }
}];
